"""One invoice: its lines, its tax, and how it is rendered."""

from dataclasses import dataclass
from decimal import Decimal

from billing.ledger import next_reference
from billing.money import format_amount, sum_amounts
from billing.tax import tax_on

INVOICE_WIDTH = 48


@dataclass(frozen=True)
class InvoiceLine:
    """One charged line on an invoice."""

    description: str
    net: Decimal
    band: str

    def tax(self) -> Decimal:
        """Return the tax due on this line."""
        return tax_on(self.net, self.band)


@dataclass(frozen=True)
class Invoice:
    """A whole invoice, identified by its reference."""

    reference: str
    lines: tuple[InvoiceLine, ...]

    def net(self) -> Decimal:
        """Total the net of every line."""
        return sum_amounts([line.net for line in self.lines])

    def gross(self) -> Decimal:
        """Total the net and the tax of every line."""
        return sum_amounts([line.net + line.tax() for line in self.lines])


def open_invoice(sequence: int, lines: tuple[InvoiceLine, ...]) -> Invoice:
    """Open an invoice under the next ledger reference."""
    return Invoice(reference=next_reference(sequence), lines=lines)


def render_invoice(invoice: Invoice) -> str:
    """Render an invoice as plain text, one line per charge."""
    if not invoice.lines:
        return f"{invoice.reference}: nothing charged\n"

    rendered = [invoice.reference, "-" * INVOICE_WIDTH]
    for line in invoice.lines:
        label = line.description.ljust(28)
        rendered.append(f"{label}{format_amount(line.net + line.tax())}")
    rendered.append("-" * INVOICE_WIDTH)
    rendered.append(f"{'gross'.ljust(28)}{format_amount(invoice.gross())}")
    return "\n".join(rendered) + "\n"

"""Amount arithmetic and formatting for the billing package."""

from decimal import ROUND_HALF_UP, Decimal

BILLING_CURRENCY = "GBP"
BILLING_PRECISION = Decimal("0.01")


def round_amount(amount: Decimal) -> Decimal:
    """Round an amount to the billing precision, half away from zero."""
    return amount.quantize(BILLING_PRECISION, rounding=ROUND_HALF_UP)


def format_amount(amount: Decimal) -> str:
    """Render an amount with the billing currency suffix."""
    return f"{round_amount(amount)} {BILLING_CURRENCY}"


def sum_amounts(amounts: list[Decimal]) -> Decimal:
    """Total a list of amounts, rounding once at the end."""
    running = Decimal("0.00")
    for amount in amounts:
        running += amount
    return round_amount(running)

"""Tax rates and the arithmetic that applies them."""

from decimal import Decimal

from billing.money import round_amount

STANDARD_RATE = Decimal("0.20")
REDUCED_RATE = Decimal("0.05")

RATES_BY_BAND = {
    "standard": STANDARD_RATE,
    "reduced": REDUCED_RATE,
    "zero": Decimal("0.00"),
}


def rate_for_band(band: str) -> Decimal:
    """Return the tax rate for a band, refusing an unknown one."""
    try:
        return RATES_BY_BAND[band]
    except KeyError as exc:
        message = f"no tax rate is defined for band {band}"
        raise LookupError(message) from exc


def tax_on(net: Decimal, band: str) -> Decimal:
    """Return the tax due on a net amount in one band."""
    if net < 0:
        message = "a negative net amount cannot be taxed"
        raise ValueError(message)
    return round_amount(net * rate_for_band(band))

"""The catalogue record every other catalogue module reads."""

from dataclasses import dataclass

CATALOGUE_NAME = "spring"
MAX_TITLE_CHARS = 64


@dataclass(frozen=True)
class Product:
    """One saleable product in the catalogue."""

    code: str
    title: str
    band: str

    def short_title(self) -> str:
        """Return the title cut to the catalogue's column width."""
        if len(self.title) <= MAX_TITLE_CHARS:
            return self.title
        return self.title[: MAX_TITLE_CHARS - 3] + "..."


def parse_product(row: dict[str, str]) -> Product:
    """Build a product from one catalogue row, refusing a missing field."""
    for field in ("code", "title", "band"):
        if field not in row:
            message = f"catalogue row is missing {field}"
            raise KeyError(message)
    return Product(code=row["code"], title=row["title"], band=row["band"])

"""How many of each catalogue product are held."""

from catalog.product import Product

LOW_STOCK_LEVEL = 12


class StockLevels:
    """Held quantities keyed by product code."""

    def __init__(self) -> None:
        """Start with nothing held."""
        self._held: dict[str, int] = {}

    def record(self, product: Product, quantity: int) -> None:
        """Record the quantity held of one product."""
        if quantity < 0:
            message = f"{product.code} cannot hold a negative quantity"
            raise ValueError(message)
        self._held[product.code] = quantity

    def held(self, product: Product) -> int:
        """Return the quantity held, refusing an unrecorded product."""
        try:
            return self._held[product.code]
        except KeyError as exc:
            message = f"{product.code} has no recorded stock level"
            raise LookupError(message) from exc

    def is_low(self, product: Product) -> bool:
        """Say whether a product has fallen under the low-stock level."""
        return self.held(product) < LOW_STOCK_LEVEL

"""Price calculation with tiered discounts."""

from decimal import ROUND_HALF_UP, Decimal
from enum import Enum

BASE_MARKUP = Decimal("1.35")
CURRENCY = "EUR"
CENTS = Decimal("0.01")


class Tier(str, Enum):
    """Customer pricing tiers."""

    RETAIL = "retail"
    TRADE = "trade"
    WHOLESALE = "wholesale"


DISCOUNTS = {
    Tier.RETAIL: Decimal("0.00"),
    Tier.TRADE: Decimal("0.10"),
    Tier.WHOLESALE: Decimal("0.22"),
}


class PriceBook:
    """Cost prices keyed by SKU, plus the rules that turn them into quotes."""

    def __init__(self, costs: dict[str, Decimal]) -> None:
        """Hold a copy of the cost table so callers cannot mutate it later."""
        self._costs: dict[str, Decimal] = {}
        for sku, cost in costs.items():
            if cost < 0:
                message = f"negative cost price for {sku}"
                raise ValueError(message)
            self._costs[sku] = Decimal(cost)

    def cost_of(self, sku: str) -> Decimal:
        """Return the cost price for a SKU."""
        try:
            return self._costs[sku]
        except KeyError as exc:
            message = f"no cost price recorded for {sku}"
            raise LookupError(message) from exc

    def quote(self, sku: str, tier: Tier, quantity: int = 1) -> Decimal:
        """Quote a line total for a SKU at a tier."""
        if quantity < 1:
            message = "quantity must be at least one"
            raise ValueError(message)
        unit = self.cost_of(sku) * BASE_MARKUP
        # Discounts apply to the marked-up price, not the cost price.
        discount = DISCOUNTS[tier]
        discounted = unit * (Decimal("1.00") - discount)
        line_total = discounted * quantity
        return line_total.quantize(CENTS, rounding=ROUND_HALF_UP)

    def price_list(self, tier: Tier) -> list[tuple[str, Decimal]]:
        """Return every SKU with its unit price at a tier, SKU order."""
        rows: list[tuple[str, Decimal]] = []
        for sku in sorted(self._costs):
            rows.append((sku, self.quote(sku, tier)))
        return rows

    def cheapest(self, tier: Tier) -> str:
        """Return the SKU with the lowest unit price at a tier."""
        rows = self.price_list(tier)
        if not rows:
            message = "price book is empty"
            raise LookupError(message)
        best_sku, best_price = rows[0]
        for sku, price in rows[1:]:
            if price < best_price:
                best_sku, best_price = sku, price
        return best_sku


def format_money(amount: Decimal) -> str:
    """Render an amount with the configured currency suffix."""
    quantized = amount.quantize(CENTS, rounding=ROUND_HALF_UP)
    return f"{quantized} {CURRENCY}"

