"""One invoice: its lines, its tax, and how it is rendered."""

from dataclasses import dataclass
from decimal import Decimal

from billing.ledger import next_reference
from billing.money import format_amount, sum_amounts
from billing.tax import tax_on

INVOICE_WIDTH = 48


@dataclass(frozen=True)
class InvoiceLine:
    """One charged line on an invoice."""

    description: str
    net: Decimal
    band: str

    def tax(self) -> Decimal:
        """Return the tax due on this line."""
        return tax_on(self.net, self.band)


@dataclass(frozen=True)
class Invoice:
    """A whole invoice, identified by its reference."""

    reference: str
    lines: tuple[InvoiceLine, ...]

    def net(self) -> Decimal:
        """Total the net of every line."""
        return sum_amounts([line.net for line in self.lines])

    def gross(self) -> Decimal:
        """Total the net and the tax of every line."""
        return sum_amounts([line.net + line.tax() for line in self.lines])


def open_invoice(sequence: int, lines: tuple[InvoiceLine, ...]) -> Invoice:
    """Open an invoice under the next ledger reference."""
    return Invoice(reference=next_reference(sequence), lines=lines)


def render_invoice(invoice: Invoice) -> str:
    """Render an invoice as plain text, one line per charge."""
    if not invoice.lines:
        return f"{invoice.reference}: nothing charged\n"

    rendered = [invoice.reference, "-" * INVOICE_WIDTH]
    for line in invoice.lines:
        label = line.description.ljust(28)
        rendered.append(f"{label}{format_amount(line.net + line.tax())}")
    rendered.append("-" * INVOICE_WIDTH)
    rendered.append(f"{'gross'.ljust(28)}{format_amount(invoice.gross())}")
    return "\n".join(rendered) + "\n"

"""Amount arithmetic and formatting for the billing package."""

from decimal import ROUND_HALF_UP, Decimal

BILLING_CURRENCY = "GBP"
BILLING_PRECISION = Decimal("0.01")


def round_amount(amount: Decimal) -> Decimal:
    """Round an amount to the billing precision, half away from zero."""
    return amount.quantize(BILLING_PRECISION, rounding=ROUND_HALF_UP)


def format_amount(amount: Decimal) -> str:
    """Render an amount with the billing currency suffix."""
    return f"{round_amount(amount)} {BILLING_CURRENCY}"


def sum_amounts(amounts: list[Decimal]) -> Decimal:
    """Total a list of amounts, rounding once at the end."""
    running = Decimal("0.00")
    for amount in amounts:
        running += amount
    return round_amount(running)

"""Tax rates and the arithmetic that applies them."""

from decimal import Decimal

from billing.money import round_amount

STANDARD_RATE = Decimal("0.20")
REDUCED_RATE = Decimal("0.05")

RATES_BY_BAND = {
    "standard": STANDARD_RATE,
    "reduced": REDUCED_RATE,
    "zero": Decimal("0.00"),
}


def rate_for_band(band: str) -> Decimal:
    """Return the tax rate for a band, refusing an unknown one."""
    try:
        return RATES_BY_BAND[band]
    except KeyError as exc:
        message = f"no tax rate is defined for band {band}"
        raise LookupError(message) from exc


def tax_on(net: Decimal, band: str) -> Decimal:
    """Return the tax due on a net amount in one band."""
    if net < 0:
        message = "a negative net amount cannot be taxed"
        raise ValueError(message)
    return round_amount(net * rate_for_band(band))

